import{_ as i,c as t,o,ag as a}from"./chunks/framework.CQuhCYrb.js";const p=JSON.parse('{"title":"Initial Series Concept","description":"","frontmatter":{"title":"Initial Series Concept"},"headers":[],"relativePath":"general/initial-series-concept.md","filePath":"general/initial-series-concept.md","lastUpdated":null}'),r={name:"general/initial-series-concept.md"};function n(l,e,s,h,c,d){return o(),t("div",null,[...e[0]||(e[0]=[a('<h1 id="initial-series-concept" tabindex="-1">Initial Series Concept <a class="header-anchor" href="#initial-series-concept" aria-label="Permalink to &quot;Initial Series Concept&quot;">​</a></h1><h2 id="miso-series-initial-conop-enclosure-1-review-workflow" tabindex="-1">MISO Series Initial CONOP - Enclosure 1 Review Workflow <a class="header-anchor" href="#miso-series-initial-conop-enclosure-1-review-workflow" aria-label="Permalink to &quot;MISO Series Initial CONOP - Enclosure 1 Review Workflow&quot;">​</a></h2><p><strong>Purpose</strong>: To reduce variance, improve efficiency, expand continuity and interoperability, increase transparency, and allow for systemic adjustments to reviewing Series Initial CONOPs by an HQ, OPCEN, or IWTF.</p><p>The Enclosure 1/Initial MISO Series CONOP is intended to capture the COA for approval. PSYOP Planning, in accordance with FM 3-53 and MDMP/JPP, should drive this process, not starting with the end product and copy-pasting or presenting options without appropriate planning and consideration.</p><p>OPCEN will ensure this by following the SOP by the numbers. Based on updated doctrine, policy, guidance, or experience, changes may be recommended.</p><p>These comments and changes made by the OPCEN are only recommendations, and the TEAM with the Ground Truth has the final say. OPCEN will ask about any recommendations that were not applied during the Series Review Board (SRB), where teams can provide their reasons from the ground truth.</p><p><strong>NOTE</strong>: (comments)</p><h2 id="comment-bubble-should-highlight-the-general-area-which-the-comment-belongs-to" tabindex="-1">Comment bubble should highlight the general area which the comment belongs to. <a class="header-anchor" href="#comment-bubble-should-highlight-the-general-area-which-the-comment-belongs-to" aria-label="Permalink to &quot;Comment bubble should highlight the general area which the comment belongs to.&quot;">​</a></h2><h2 id="be-as-specific-as-possible-with-comments" tabindex="-1">Be as specific as possible with comments. <a class="header-anchor" href="#be-as-specific-as-possible-with-comments" aria-label="Permalink to &quot;Be as specific as possible with comments.&quot;">​</a></h2><h2 id="if-there-is-a-required-change-based-on-policy-authorities-or-j39-guidance-add-the-following-to-the-start-of-the-comment" tabindex="-1">If there is a required change based on Policy, Authorities, or J39 Guidance, add the following to the start of the comment: <a class="header-anchor" href="#if-there-is-a-required-change-based-on-policy-authorities-or-j39-guidance-add-the-following-to-the-start-of-the-comment" aria-label="Permalink to &quot;If there is a required change based on Policy, Authorities, or J39 Guidance, add the following to the start of the comment:&quot;">​</a></h2><ul><li>&quot;<strong>REQUIRED CHANGE</strong>:&quot; **</li><li>All other comments will be seen as recommendations.**</li></ul><h3 id="location" tabindex="-1">Location <a class="header-anchor" href="#location" aria-label="Permalink to &quot;Location&quot;">​</a></h3><p>Working copy to initiate series review: SOCSOUTH J39 PSYOP (SIPR) &gt; In Development &gt; Country &gt; Series Name &gt; 1. Enclosures &gt; Enclosure 1 &gt; Working</p><p>Copy Ready for Review and Approval should be: SOCSOUTH J39 PSYOP (SIPR) &gt; In Development &gt; Country &gt; Series Name &gt; 1. Enclosures &gt; Enclosure 1 &gt; FILE-HERE</p><h3 id="broad-steps" tabindex="-1">Broad Steps <a class="header-anchor" href="#broad-steps" aria-label="Permalink to &quot;Broad Steps&quot;">​</a></h3><h2 id="ensure-task-is-in-the-opcen-rfs-tracker" tabindex="-1">Ensure Task is in the OPCEN RFS Tracker. <a class="header-anchor" href="#ensure-task-is-in-the-opcen-rfs-tracker" aria-label="Permalink to &quot;Ensure Task is in the OPCEN RFS Tracker.&quot;">​</a></h2><h2 id="upload-enclosure-to-sipr-portal" tabindex="-1">Upload Enclosure to SIPR Portal. <a class="header-anchor" href="#upload-enclosure-to-sipr-portal" aria-label="Permalink to &quot;Upload Enclosure to SIPR Portal.&quot;">​</a></h2><ul><li>Name file: SERIES-NAME-YYYY-MM_Comments.**</li></ul><h2 id="review-past-guidance" tabindex="-1">Review past guidance. <a class="header-anchor" href="#review-past-guidance" aria-label="Permalink to &quot;Review past guidance.&quot;">​</a></h2><h2 id="initial-contact-with-the-team" tabindex="-1">Initial contact with the Team. <a class="header-anchor" href="#initial-contact-with-the-team" aria-label="Permalink to &quot;Initial contact with the Team.&quot;">​</a></h2><h2 id="read-enclosure" tabindex="-1">Read Enclosure. <a class="header-anchor" href="#read-enclosure" aria-label="Permalink to &quot;Read Enclosure.&quot;">​</a></h2><h2 id="review-and-validate-with-comments" tabindex="-1">Review and validate with comments. <a class="header-anchor" href="#review-and-validate-with-comments" aria-label="Permalink to &quot;Review and validate with comments.&quot;">​</a></h2><h2 id="contact-with-team-rfis-in-depth-deconflict" tabindex="-1">Contact with Team (RFIs, in-depth, deconflict). <a class="header-anchor" href="#contact-with-team-rfis-in-depth-deconflict" aria-label="Permalink to &quot;Contact with Team (RFIs, in-depth, deconflict).&quot;">​</a></h2><h2 id="confirm-attributes-with-comments" tabindex="-1">Confirm Attributes with comments. <a class="header-anchor" href="#confirm-attributes-with-comments" aria-label="Permalink to &quot;Confirm Attributes with comments.&quot;">​</a></h2><h2 id="confirm-formatting" tabindex="-1">Confirm Formatting. <a class="header-anchor" href="#confirm-formatting" aria-label="Permalink to &quot;Confirm Formatting.&quot;">​</a></h2><h2 id="copy-enclosure-to-the-same-location" tabindex="-1">Copy Enclosure to the same location: <a class="header-anchor" href="#copy-enclosure-to-the-same-location" aria-label="Permalink to &quot;Copy Enclosure to the same location:&quot;">​</a></h2><ul><li>Name file: SERIES-NAME-YYYY-MM_Changes.**</li></ul><h2 id="apply-corrections-and-recommendations" tabindex="-1">Apply corrections and recommendations. <a class="header-anchor" href="#apply-corrections-and-recommendations" aria-label="Permalink to &quot;Apply corrections and recommendations.&quot;">​</a></h2><h2 id="submit-for-review-bluf-must-include-required-changes" tabindex="-1">Submit for review (BLUF must include REQUIRED changes). <a class="header-anchor" href="#submit-for-review-bluf-must-include-required-changes" aria-label="Permalink to &quot;Submit for review (BLUF must include REQUIRED changes).&quot;">​</a></h2><ul><li>OPCEN Leadership.**</li><li>Company Leadership.**</li></ul><h3 id="steps-taken-for-enclosure-1-review" tabindex="-1">Steps Taken for Enclosure 1 Review <a class="header-anchor" href="#steps-taken-for-enclosure-1-review" aria-label="Permalink to &quot;Steps Taken for Enclosure 1 Review&quot;">​</a></h3><ol><li><strong>Ensure that task is in the RFS Tracker</strong>: <a href="https://socom.sharepoint-mil.us/:l:/s/usasoc-1sfc-4pog-1bn-c/FKFS5PZyXDlAqKWw8vtI16MB8QlVLYOcNUeHJVbj2U27eg?e=Thht51" target="_blank" rel="noreferrer">OPCEN RFS</a></li></ol><ul><li><p>If the task is not in the RFS Tracker, add it and include the requester&#39;s email and team appropriately.</p></li><li><p>When it is on the RFS tracker, assign yourself and change the status of the RFS as you work on it.</p></li></ul><h2 id="upload-enclosure-to-sipr-portal-1" tabindex="-1">Upload Enclosure to SIPR Portal. <a class="header-anchor" href="#upload-enclosure-to-sipr-portal-1" aria-label="Permalink to &quot;Upload Enclosure to SIPR Portal.&quot;">​</a></h2><ul><li><p>Create directory in Country Directory.</p><ul><li>Directory should be: IN DEVELOPMENT-COUNTRY-SERIES-SERIES ENCLOSURES-ENCLOSURE 1-WORKING. **(Note: Original submission goes into ENC 1 folder. Save a copy in the working folder using naming convention below.)</li></ul></li><li><p>Name file: SERIES-NAME-YYYY-MM_Comments.</p></li><li><p>Add link to working directory in chatsurfer (SIPR).</p></li></ul><ol><li><strong>Review past guidance</strong> from the J39 about Enclosure 1.</li></ol><ul><li><p>Review PSYOP Kneeboard <strong>[Series Overview]</strong>: (SIPR): <code>https://YOURTSOC.smil.mil/sites/J39/Kneeboards/</code></p><ul><li>Find the most current version.</li><li>Review the intent of series groups and ensure MO/SMO/DB align with Kneeboard exactly since the MO/SMO/DB are set for REVIVAL/ALLIANCE/VOICE regionally. Supporting MISO behaviors vary between countries and are laid out according to the HPEM model.</li></ul></li><li><p>Review Objectives and Effects (J5 SIPR): <code>https://YOURTSOC.smil.mil/sites/j5/SOFAssessments/</code></p></li><li><p>Review TSOC CONOP/EXORD Guidance being used by the series: <code>https://YOURTSOC.smil.mil/sites/Ops/J35/plans/CONOPs</code></p></li><li><p>Ensure SMO / Desired Behavior and assessment criteria are aligned with the Hierarchy of Psychological Effects Model (HPEM) (TM 3-53.11 Chapter 2).</p></li><li><p>Check for portion markings that are not overclassified or missing.</p></li></ul><ol><li><strong>Contact team for initial communications.</strong></li></ol><ul><li>Send email to Team, CC DET Leadership and FUOPS Leadership. <ul><li>Goal is to establish a communication channel for future discussion and clarify who is working on the RFS and who is the customer of the RFS.</li></ul></li></ul><ol><li><strong>Read</strong> entire Enclosure 1.</li></ol><ul><li><p>Review header slide (slide 1) for correct series name and team information.</p></li><li><p>Write down questions.</p></li><li><p>Review Background statement.</p><ul><li>Should not focus on what the series will do but rather on the situation and the issues needing mitigation.</li></ul></li><li><p>Avoid making any corrections or recommendations yet.</p></li></ul><ol><li><strong>Validate attributes with the MISO Plan</strong> referenced in the Enclosure 1.</li></ol><ul><li>Locate MISO Program: <ul><li>MISO Plan referenced in CONPLAN/OPORD, Campaign support plan.</li><li>MISO Objective.</li><li>Potential Target Audience List (PTAL).</li><li>Classification of attributes.</li></ul></li></ul><ol><li><strong>Contact Teams with input and questions.</strong> (after sending questions and communication, move to the next step).</li></ol><ul><li><p>Deconflict any irregularities found.</p></li><li><p>Request the INTEL and open-source reports that were used in the planning of this enclosure.</p></li><li><p>Understand the planning process:</p><ul><li>Can you walk me through how the (Effect / SMO / PTAL / DB) was reached?</li><li>What else was considered?</li><li>Why didn&#39;t those options work?</li></ul></li><li><p>Understand friendly assessment capability:</p><ul><li>How do you plan on obtaining the initial assessment criteria (broad; this will help in reviewing each specific criterion)?</li></ul></li></ul><ol><li><strong>Confirm Effect</strong> meets intended Goal or LOE.</li></ol><ul><li>Stick with one that is copied straight from the J5 SOCAT Objectives and Effects Crosswalk.</li></ul><ol><li><strong>Confirm SMO / SPO meets Desired Effect:</strong> is <strong>specific</strong>, <strong>measurable</strong>, and <strong>observable</strong> to be effectively targeted (TM 3-53.11 3-3).</li></ol><ul><li><p>Is the SMO specific enough to avoid confusion with other SMOs?</p></li><li><p>Is the SMO observable, not taking place in private or in a manner that can&#39;t be observed?</p></li><li><p>Is the SMO measurable with current friendly capabilities?</p></li></ul><ol><li><strong>Confirm Desired Behavior meets SMO:</strong></li></ol><ul><li><p>Is it directly tied to the SMO?</p></li><li><p>Does it have the opportunity to occur in the required location or environment?</p></li></ul><ol><li><strong>Confirm Potential Target Audience List (PTAL) can achieve the Desired Behavior:</strong> This will be refined in the next enclosure, but all the PTAs listed must originate from the designated MISO Program and:</li></ol><ul><li><p>Have the capability (physical, social, cognitive ability) to perform the desired behavior.</p></li><li><p>Have the opportunity to perform the behavior in their typical environment.</p></li><li><p>Have the motivation to perform the desired behavior.</p></li></ul><ol><li><strong>Validate Initial Assessment Criteria</strong> focused on the target audience (TA) moving along the Hierarchy of Psychological Effects Model (HPEM) to behavior. In planning, it may be best to reverse plan. These should be measurable but will be refined and validated into the refined assessment criteria in the TAAW. The SMO needs to be the primary focus, not any assumptions or second-order effects derived from the SMO. List this initial assessment criteria in this order.</li></ol><ul><li><p><strong>Behavior</strong>: Questions like:</p><ul><li>How many TA have attended/participated in/performed desired behavior?</li></ul></li><li><p><strong>Intention</strong> of performing behavior:</p><ul><li>How many TA have signed up to attend, have added to shopping cart, RSVP&#39;d?</li></ul></li><li><p><strong>Preference</strong> for behavior:</p><ul><li>How many TA have joined or subscribed to pages, profiles, or newsletters about the action?</li></ul></li><li><p><strong>Sentiment</strong> towards behavior:</p><ul><li>How many TA have engaged positively or negatively?</li></ul></li><li><p><strong>Understanding</strong> of performing behavior or context of behavior:</p><ul><li>How many TA have questioned, commented, engaged with?</li></ul></li><li><p><strong>Awareness</strong> of behavior or context of behavior:</p><ul><li>How many TA have seen xyz?</li></ul></li><li><p>INTEL reviews for collection capability.</p></li></ul><h2 id="submit-for-review" tabindex="-1">Submit for review. <a class="header-anchor" href="#submit-for-review" aria-label="Permalink to &quot;Submit for review.&quot;">​</a></h2><ul><li><p>BLUF must include the REQUIRED changes, which are changes due to authorities, policy, and J39 guidance.</p></li><li><p>Submit to the following in order:</p><ul><li>OPCEN Leadership (Direct link to the directory holding the 2 documents).</li><li>Company Leadership.</li><li>Leadership will return to the team (team preferred method).</li></ul></li><li><p>After ENC 1 is CMD reviewed and approved through the board, rename ENC 1 to SERIES NAME_ENC 1_date (year month 202405)_FINAL.</p></li></ul><p>[Up] [Required]</p>',58)])])}const m=i(r,[["render",n]]);export{p as __pageData,m as default};
